// word-weaver/js/data-test-es.js - headless checks of Word Weaver's SPANISH levels (word-weaver/data/es/,
// GENERATED by tools/build-word-weaver-es.mjs, 2026-10-29). Run: node word-weaver/js/data-test-es.js
// data-test.js's checks, with Ñ as a 27th letter and no accents; "a real word" is the generator's job
// (Spelling Bee's Spanish sources), not re-checked here.
//
// Every level is checked against the rules the game relies on: the files' shape (index + chunks of
// 250), the wheel (3-7 letters, sorted, uppercase), the crossword (every word fits the wheel, words
// cross only on the same letter, one connected grid, no two letters touching unless a word runs
// through both, no word twice, inside g and at most 9 x 9, the base word using every letter is in
// it), and the extras (sorted, uppercase, 3+ letters, formable, real ENABLE words, never a grid
// word, and complete: any word accepted on SOME level is accepted on every level that can make it).
// Then the first SHIPPED levels are pinned by hash: a player's progress is per level number
// (js/word-weaver-points.js), so the levels are APPEND-ONLY once shipped.
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';

const DATA = new URL('../data/es/', import.meta.url);
let fails = 0;
const failed = [];
const ok = (label, cond) => { if (!cond) { fails++; if (failed.length < 40) failed.push(label); } };

// --- the files ---------------------------------------------------------------------------------
const index = JSON.parse(readFileSync(new URL('index.json', DATA), 'utf8'));
ok('index: { v: 1, count, chunk: 250 }', index.v === 1 && Number.isInteger(index.count) && index.count > 0 && index.chunk === 250
  && Object.keys(index).sort().join() === 'chunk,count,v');
const LEVELS = [];
for (let k = 0; k * index.chunk < index.count; k++) {
  const part = JSON.parse(readFileSync(new URL(`levels-${k}.json`, DATA), 'utf8'));
  ok(`chunk ${k}: { v: 1, first: ${1 + 250 * k}, levels }`, part.v === 1 && part.first === 1 + 250 * k && Array.isArray(part.levels)
    && Object.keys(part).sort().join() === 'first,levels,v');
  const want = Math.min(index.chunk, index.count - k * index.chunk);
  ok(`chunk ${k}: ${want} levels`, part.levels.length === want);
  LEVELS.push(...part.levels);
}
ok('index count = levels in the chunks', LEVELS.length === index.count);
let extraChunk = true;
try { readFileSync(new URL(`levels-${Math.ceil(index.count / index.chunk)}.json`, DATA)); } catch { extraChunk = false; }
ok('no chunk past the count', !extraChunk);

// --- every level -------------------------------------------------------------------------------
const counts = (w) => { const c = new Uint8Array(27); for (const ch of w) c[ch === 'Ñ' ? 26 : ch.charCodeAt(0) - 65]++; return c; };
const fits = (wc, lc) => { for (let i = 0; i < 27; i++) if (wc[i] > lc[i]) return false; return true; };
const sorted = (a) => a.every((w, i) => i === 0 || a[i - 1] < w);

/** The crossword rules; returns problems (empty = good). */
function gridProblems(lv) {
  const bad = [];
  const [rows, cols] = lv.g;
  const cells = new Map();
  for (const [w, r0, c0, d] of lv.w) {
    for (let i = 0; i < w.length; i++) {
      const r = d === 'd' ? r0 + i : r0, c = d === 'a' ? c0 + i : c0;
      if (r < 0 || c < 0 || r >= rows || c >= cols) { bad.push(`${w} leaves the grid`); continue; }
      const k = r * 16 + c, cell = cells.get(k);
      if (cell && cell.ch !== w[i]) bad.push(`${w} crosses on a different letter at ${r},${c}`);
      if (cell && cell[d]) bad.push(`${w} runs along another ${d} word at ${r},${c}`);
      const next = cell || { ch: w[i] };
      next[d] = w;
      cells.set(k, next);
    }
  }
  // Every run of 2+ letters in a row or column is exactly one grid word (no junk, no touching ends).
  const starts = new Set(lv.w.map(([w, r0, c0, d]) => `${d}${r0},${c0},${w.length}`));
  for (const d of ['a', 'd']) {
    const lines = d === 'a' ? rows : cols, len = d === 'a' ? cols : rows;
    for (let x = 0; x < lines; x++) {
      let run = 0;
      for (let y = 0; y <= len; y++) {
        const k = d === 'a' ? x * 16 + y : y * 16 + x;
        if (y < len && cells.has(k)) { run++; continue; }
        if (run >= 2 && !starts.has(d === 'a' ? `a${x},${y - run},${run}` : `d${y - run},${x},${run}`)) bad.push(`letters touch (${d} ${x},${y - run})`);
        run = 0;
      }
    }
  }
  // Every row and column of g is used (g is the bounding box, not a loose frame).
  const usedR = new Set([...cells.keys()].map((k) => Math.floor(k / 16))), usedC = new Set([...cells.keys()].map((k) => k % 16));
  if (usedR.size !== rows || usedC.size !== cols) bad.push('g is bigger than the grid');
  // One connected grid.
  const cellsOf = lv.w.map(([w, r0, c0, d]) => [...w].map((_, i) => (d === 'd' ? r0 + i : r0) * 16 + (d === 'a' ? c0 + i : c0)));
  const seen = new Set([0]), todo = [0];
  while (todo.length) {
    const i = todo.pop();
    for (let j = 0; j < lv.w.length; j++) if (!seen.has(j) && cellsOf[j].some((k) => cellsOf[i].includes(k))) { seen.add(j); todo.push(j); }
  }
  if (seen.size !== lv.w.length) bad.push('not one connected grid');
  return bad;
}

const vocab = new Set();
const keys = [];
for (let i = 0; i < LEVELS.length; i++) {
  const n = i + 1, lv = LEVELS[i], at = `level ${n}`;
  if (!lv || typeof lv !== 'object' || Object.keys(lv).join() !== 'l,g,w,x') { ok(`${at}: keys l, g, w, x`, false); continue; }
  const L = lv.l;
  ok(`${at}: wheel is 3-7 uppercase letters, sorted`, typeof L === 'string' && /^[A-ZÑ]{3,7}$/.test(L) && [...L].sort().join('') === L);
  ok(`${at}: g is [rows, cols], 1-9 each`, Array.isArray(lv.g) && lv.g.length === 2 && lv.g.every((x) => Number.isInteger(x) && x >= 1 && x <= 9));
  ok(`${at}: w is a list of [WORD, r, c, a|d]`, Array.isArray(lv.w) && lv.w.length >= 3 && lv.w.every((e) => Array.isArray(e) && e.length === 4
    && /^[A-ZÑ]{3,7}$/.test(e[0]) && Number.isInteger(e[1]) && Number.isInteger(e[2]) && (e[3] === 'a' || e[3] === 'd')));
  ok(`${at}: x is a sorted list of uppercase words`, Array.isArray(lv.x) && lv.x.every((w) => /^[A-ZÑ]{3,7}$/.test(w)) && sorted(lv.x));
  if (!Array.isArray(lv.w) || !Array.isArray(lv.x) || typeof L !== 'string') continue;
  const lc = counts(L);
  const words = lv.w.map((e) => e[0]);
  ok(`${at}: no grid word twice`, new Set(words).size === words.length);
  ok(`${at}: every grid word fits the wheel`, words.every((w) => fits(counts(w), lc)));
  ok(`${at}: the base word (all ${L.length} letters) is in the grid`, words.some((w) => w.length === L.length));
  ok(`${at}: every extra fits the wheel`, lv.x.every((w) => fits(counts(w), lc)));
  ok(`${at}: no accents anywhere`, [L, ...words, ...lv.x].every((w) => !/[ÁÉÍÓÚÜ]/.test(w)));
  ok(`${at}: extras never repeat a grid word`, lv.x.every((w) => !words.includes(w)));
  const problems = gridProblems(lv);
  ok(`${at}: crossword: ${problems.join('; ')}`, problems.length === 0);
  for (const w of words) vocab.add(w);
  for (const w of lv.x) vocab.add(w);
  keys.push(L);
}

// Extras are complete: a word accepted anywhere is accepted wherever the wheel can make it.
{
  const V = [...vocab].map((w) => [w, counts(w)]);
  let missing = 0, example = '';
  for (let i = 0; i < LEVELS.length; i++) {
    const lv = LEVELS[i], lc = counts(lv.l);
    const have = new Set([...lv.w.map((e) => e[0]), ...lv.x]);
    for (const [w, wc] of V) if (w.length <= lv.l.length && !have.has(w) && fits(wc, lc)) { missing++; if (!example) example = `level ${i + 1} misses ${w}`; }
  }
  ok(`extras are complete (${missing} missing; ${example})`, missing === 0);
}

// --- the ramp ----------------------------------------------------------------------------------
ok('levels 1-10: 3-4 wheel letters, 3-4 grid words', LEVELS.slice(0, 10).every((lv) => lv.l.length <= 4 && lv.w.length >= 3 && lv.w.length <= 4));
ok('never the same letters twice in a row', keys.every((k, i) => i === 0 || keys[i - 1] !== k));
ok('no letter multiset is used twice anywhere', new Set(keys).size === keys.length);
ok('7-letter wheels arrive by level 500', LEVELS.slice(0, 500).some((lv) => lv.l.length === 7));

// --- Hard and Expert (2026-10-29): their own rules (tools/build-word-weaver-data.mjs, BAND) ------
const BANDS = [
  { name: 'Hard', from: 1001, to: 1500, minLen: 3, max3: 1, max4: 4, words: [7, 12] },
  { name: 'Expert', from: 1501, to: 2000, minLen: 4, max3: 0, max4: 4, words: [8, 13] },
];
for (const B of BANDS) {
  const part = LEVELS.slice(B.from - 1, B.to);
  const bad = (f) => part.map((lv, i) => (f(lv) ? 0 : B.from + i)).filter(Boolean).slice(0, 5).join(', ');
  const len = (lv, n) => lv.w.filter((e) => e[0].length === n).length;
  let b;
  ok(`${B.name}: every level has 7 wheel letters (${b = bad((lv) => lv.l.length === 7)})`, !b);
  ok(`${B.name}: ${B.words[0]}-${B.words[1]} grid words (${b = bad((lv) => lv.w.length >= B.words[0] && lv.w.length <= B.words[1])})`, !b);
  ok(`${B.name}: no grid word under ${B.minLen} letters (${b = bad((lv) => lv.w.every((e) => e[0].length >= B.minLen))})`, !b);
  ok(`${B.name}: at most ${B.max3} three- and ${B.max4} four-letter grid words (${b = bad((lv) => len(lv, 3) <= B.max3 && len(lv, 4) <= B.max4)})`, !b);
}
{
  const avgLen = (a, z) => { const ws = LEVELS.slice(a - 1, z).flatMap((lv) => lv.w.map((e) => e[0].length)); return ws.reduce((p, q) => p + q, 0) / ws.length; };
  ok('Expert grid words are longer on average than Medium\'s, Hard\'s than Medium\'s', avgLen(1501, 2000) > avgLen(501, 1000) + 0.3 && avgLen(1001, 1500) > avgLen(501, 1000) + 0.2);
}

// --- the pin -----------------------------------------------------------------------------------
// Spanish levels are APPEND-ONLY once shipped too (progress is per level number, `ww.es`).
{
  const big = LEVELS.slice(500).filter((lv) => lv.g[0] > 7 || lv.g[1] > 7).length;
  ok(`every board past Easy is at most 7 x 7 (${big} bigger; remade 2026-10-30)`, big === 0);
}
const PINNED = 2000;
const PIN_HASH = '22a56210113a70d4';
if (PINNED) {
  const h = createHash('sha256').update(LEVELS.slice(0, PINNED).map((lv) => JSON.stringify(lv)).join('\n')).digest('hex').slice(0, 16);
  ok(`pin: the first ${PINNED} shipped Spanish levels are unchanged (${h})`, LEVELS.length >= PINNED && h === PIN_HASH);
}
{
  const n = LEVELS.filter((lv) => lv.l.includes('Ñ')).length;
  ok(`Ñ is a letter of some wheels (${n})`, n >= 10);
}

for (const f of failed) console.log('FAIL ', f);
console.log(fails ? `${fails} FAILED` : `ok: ${LEVELS.length} Spanish levels, ${vocab.size} distinct words`);
process.exit(fails ? 1 : 0);
